window.DRILLS = {"L4": {"video": "drill_l4", "title": "Reset Speed", "tag": "SETBACK", "nar": ["Time for the drill. This one is about how quickly you recover when something goes wrong.", "Press Play. The video pauses a few times so you can answer, and it resumes when you're done."], "opts": ["Delay or cancel what's next", "Show up and act like nothing happened", "Show up, name it briefly and move forward", "Show up and let the frustration spill into it"], "optsAt": [51.25, 54.2, 57.4, 61.1], "beats": [{"t": 0.45, "u": 13.4, "kind": "shift", "text": "Something didn't go the way you hoped. You have something else that needs your full attention, in 15 minutes."}, {"t": 13.45, "u": 21.4, "kind": "notice", "text": "What is still with you from what just happened?"}, {"t": 36.45, "u": 49.3, "kind": "reframe", "text": "How long the last moment controls the next one has a name: reset speed. Like an athlete's recovery between reps, it can be conditioned."}, {"t": 51.25, "u": 64.95, "kind": "options", "text": "Your options"}, {"t": 75.8, "u": 82.2, "kind": "again", "text": "One more thing just went wrong, right on top of this."}, {"t": 87.95, "u": 103.2, "kind": "condition", "text": "Time yourself this week. After something goes wrong, how long before you're fully present for the next thing? Try to shorten the gap."}], "holds": [{"t": 21.45, "resume": 36.25, "key": "notice", "kind": "text", "label": "NOTICE", "q": "Before you decide what to do next, what's still with you from what just happened? Name it, even briefly."}, {"t": 64.95, "resume": 75.65, "key": "choose", "kind": "choice", "label": "CHOOSE", "q": "Your next meeting starts in 15 minutes. What do you do?"}, {"t": 82.2, "resume": 87.75, "key": "again", "kind": "choice", "label": "GO AGAIN", "q": "One more thing just went wrong. What do you do now?"}]}};
